import{z as o,x as n,o as e,c as p,q as i,j as r,D as E,d as l,s,S as B,b as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"胶的老化与保质","description":"","frontmatter":{"title":"胶的老化与保质","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-shelf-life.md","filePath":"litho/resist-shelf-life.md","lastUpdated":1791063341000}'),d={name:"litho/resist-shelf-life.md"};function h(m,a,_,f,P,D){const A=n("Mermaid");return e(),p("div",null,[a[2]||(a[2]=i('<h1 id="胶的老化与保质" tabindex="-1">胶的老化与保质 <a class="header-anchor" href="#胶的老化与保质" aria-label="Permalink to &quot;胶的老化与保质&quot;">​</a></h1><div class="epigraph"><p>配方在桶里也会走：溶剂挥发、PAG 分解、吸水与胺污染把 $E_0$ 和 $T_g$ 一起搬走。保质期是化学库存，不是物流标签。</p><footer>—— 据抗蚀剂贮存与老化的产线通称；PAG 稳定性讨论见 Mack / 配方公开叙述</footer></div><p><a href="/litho/tg-free-volume">上一课</a>把 \\(T_g\\) 与自由体积写成膜内坐标。缺口是时间：同一桶胶，开封前后、冷藏断链、晶圆上涂完再等，材料已经不是标定批次。本课钉老化与保质。涂完立刻那一截溶剂账，留给<a href="/litho/pab-solvent">下一课</a>的 PAB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>未开封冷藏主要防 PAG 热分解与溶剂配比漂移。开封后多了吸湿、环境胺、瓶内液面上空间的挥发。结果：\\(E_0\\) 抬或降（视 PAG 损失还是增塑上升）、暗侵蚀变、颗粒升、\\(\\gamma\\) 钝。把「剂量环自己漂了」当成扫描机故障，有时只是胶龄过了资格窗。</p><p>晶圆上的延迟：涂胶到曝光、曝光到 PEB，属于轨道时间规，不是桶的保质期，但机制同类——胺与湿气。本课两者都承认，签核要分开写：桶龄 vs 晶圆等待。</p><p><span class="marginnote">直觉类比：抗蚀剂像牛奶——桶上印的日期不是物流信息，而是化学承诺。开封等于把保护体系撤掉一半：吸湿、吸胺、挥发同时加速；冷藏只是把这条劣化曲线压慢，不是按了暂停键。</span></p><p>缺口不是再写 CAR 循环，而是：ABC、\\(E_0\\)、\\(\\ell\\) 都对龄期敏感，模型版本必须与批次日期绑定。</p><h3 id="灵敏度上升不一定是好事" tabindex="-1">灵敏度上升不一定是好事 <a class="header-anchor" href="#灵敏度上升不一定是好事" aria-label="Permalink to &quot;灵敏度上升不一定是好事&quot;">​</a></h3><p>部分老化路径让抑制剂或淬灭剂先耗掉，看起来更敏，暗区起雾、T-top 一起到。只盯 \\(E_0\\) 下降会把过期胶当成「更优配方」。</p><p><span class="marginnote">EUV 金属氧化物分散液的团聚与沉淀是另一族老化，颗粒和 LCDU 先坏。不要把 CAR 冷藏规则复印到 MOR 瓶上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>资格：强制冷藏温度、开封后使用时数、避光、氮封。监控：黏度（固含）、含水量、\\(E_0\\) 监控片、缺陷密度。断冷链要重新资格，不能靠「看起来还能涂」。轨道上：涂–曝、曝–PEB 延迟矩阵是老化的晶圆版，与<a href="/litho/pag-quencher">淬灭剂</a>课的环境胺实验是同一类判据。</p><p>换批次验收必须含老化加速（高温短时）与真实冷藏对照，方向一致才承认机制，不能只用加速来外推年。</p><p><span class="marginnote">数字实例：若 PAG 每月热分解约 2%，室温存放半年与冷库存放半年相比，产酸库存可以差出好几个百分点——剂量监控环看到的已经不是标定时的那一桶，正常批间剂量差会被胶龄差伪装。</span></p>',15)),(e(),r(B,null,{default:E(()=>[s(A,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20STORE%5B%22%E6%A1%B6%E9%BE%84%20%2F%20%E5%86%B7%E9%93%BE%22%5D%20--%3E%20CHEM%5B%22PAG%20%E6%BA%B6%E5%89%82%20%E6%B0%B4%20%E8%83%BA%22%5D%0A%20%20WAIT%5B%22%E6%99%B6%E5%9C%86%E7%AD%89%E5%BE%85%22%5D%20--%3E%20CHEM%0A%20%20CHEM%20--%3E%20E0%5B%22E0%20%2F%20%CE%B3%20%2F%20%E9%A2%97%E7%B2%92%22%5D%0A%20%20CHEM%20--%3E%20TG%5B%22%E6%9C%89%E6%95%88%20Tg%22%5D%0A%20%20E0%20--%3E%20HOLD%5B%22%E8%B5%84%E6%A0%BC%E7%AA%97%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("h2",{id:"机制",tabindex:"-1"},[l("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=t("p",null,"PAG 热分解减少产酸，抬 \\(E_0\\)。溶剂挥发提高固含，膜厚与黏度变，swing 工作点挪。吸水增塑，自由体积涨，\\(\\ell\\) 与回流窗口变。胺中和顶部酸，T-top。颗粒来自团聚或析出，成为随机缺陷的系统伪装——重复出现在同一涂胶头指纹上的，不是光子泊松。",-1)),(e(),r(B,null,{default:E(()=>[s(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20THERM%5B%22PAG%20%E7%83%AD%E5%88%86%E8%A7%A3%22%5D%20--%3E%20E0UP%5B%22E0%20%E6%8A%AC%20%2F%20%E5%89%82%E9%87%8F%E6%BC%82%22%5D%0A%20%20EVAP%5B%22%E6%BA%B6%E5%89%82%E6%8C%A5%E5%8F%91%22%5D%20--%3E%20SOLID%5B%22%E5%9B%BA%E5%90%AB%E4%B8%8E%E9%BB%8F%E5%BA%A6%E6%BC%82%E7%A7%BB%22%5D%0A%20%20H2O%5B%22%E5%90%B8%E6%B0%B4%E5%A2%9E%E5%A1%91%22%5D%20--%3E%20LUP%5B%22%E6%89%A9%E6%95%A3%E9%95%BF%E5%BA%A6%E4%B8%8E%E5%9B%9E%E6%B5%81%E7%AA%97%E5%8F%98%22%5D%0A%20%20AMINE%5B%22%E7%8E%AF%E5%A2%83%E8%83%BA%22%5D%20--%3E%20TTOP%5B%22T-top%20%2F%20%E6%9A%97%E4%BE%B5%E8%9A%80%22%5D%0A%20%20AGG%5B%22%E5%9B%A2%E8%81%9A%20%2F%20%E6%9E%90%E5%87%BA%22%5D%20--%3E%20DEF%5B%22%E9%A2%97%E7%B2%92%E7%BC%BA%E9%99%B7%E4%BC%AA%E8%A3%85%E6%88%90%E9%9A%8F%E6%9C%BA%22%5D%0A%20%20QUEN%5B%22%E6%B7%AC%E7%81%AD%E5%89%82%E5%85%88%E8%80%97%22%5D%20--%3E%20SENS%5B%22%E5%81%87%E6%80%A7%E6%9B%B4%E6%95%8F%20%2B%20%E6%9A%97%E5%8C%BA%E8%B5%B7%E9%9B%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=i('<p>Dill \\(C\\) 对老化 PAC 会变；CAR 的有效 \\(C\\) 同样。紧凑模型不重提参数，只是把整套 \\(E_0\\) 当新胶。</p><p><span class="marginnote">光管与黄光区不是无限安全：近紫外仍能慢曝光 PAG。避光规对开封瓶有效，对已经涂在晶圆上的膜更有效。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某品牌的月数保质。不把加速老化的 Arrhenius 外推当成物理定律。下一课 PAB 处理的是涂布后受控赶溶剂，对象是新鲜膜；用 PAB 去「救」过期桶，只是把固含问题变成另一张不合格膜。</p><p><span class="marginnote">常见误区：缺陷「随机」出现就归给光子泊松噪声。老化析出的颗粒会重复落在同一涂胶头的指纹位置上——真随机缺陷不认设备。判据是按涂胶头分桶统计，而不是数单点出现次数。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>保质期改 PAG、溶剂、水、胺，从而改 \\(E_0\\)、\\(\\gamma\\)、颗粒与有效 \\(T_g\\)。</li><li>桶龄与晶圆等待要分规；两者都能扮扫描机剂量故障。</li><li>更敏可能是淬灭剂先死，不是更好的胶。</li><li>模型与批次日期绑定。</li><li>出处：抗蚀剂贮存通称；Mack 对配方稳定性与延迟 PEB 的讨论。</li></ul>',7))])}const T=o(d,[["render",h]]);export{c as __pageData,T as default};
